values
  ($q$edmundston$q$, $q$Edmundston$q$, $q$New Brunswick$q$, $q$Canada$q$, $q$A francophone city on the Quebec and Maine borders — three markets meeting at one highway exit.$q$, $q$Market page$q$, $q$Car dealership marketing in Edmundston.$q$,
   $q$Edmundston sits where New Brunswick, Quebec and Maine meet. Customers come from Madawaska County, across the Quebec line and over the bridge from Maine, and most of them prefer to be served in French. A store that speaks to all three, in the right language, has very little competition online.$q$,
   $q$Dealership Marketing in Edmundston, NB | Shawn Ryder Digital$q$, $q$Local SEO, Google profile and review work for Edmundston dealerships — a francophone border market drawing from New Brunswick, Quebec and Maine.$q$,
   $q$[{"k": "City population", "v": "~16,400", "n": "Hub of Madawaska County"}, {"k": "Language", "v": "Mostly French", "n": "Service in French is expected"}, {"k": "Borders", "v": "Quebec and Maine", "n": "Both within minutes"}, {"k": "Highway", "v": "Trans-Canada (2)", "n": "Main route between the Maritimes and Quebec"}]$q$::jsonb,
   $q$[{"h": "French first", "p": "Most customers here live in French. Your website, Google profile and review replies should too — written properly, not machine-translated."}, {"h": "Three markets in one", "p": "Buyers come from New Brunswick, Témiscouata in Quebec and northern Maine. Pricing, taxes and registration differ, so clear answers online save a lot of phone calls."}, {"h": "Trans-Canada traffic", "p": "Travellers between the Maritimes and Quebec pass the door. Accurate hours and a strong Google profile capture service work from people on the road."}, {"h": "Forestry and trades", "p": "Work trucks and winter-ready vehicles matter. Content about towing, durability and service lands."}]$q$::jsonb,
   $q$[{"when": "Oct–Nov", "h": "Winter tires", "p": "Winter comes early in the northwest. Open bookings before the first snow."}, {"when": "Dec–Mar", "h": "Deep winter", "p": "Heavy snow drives AWD, remote start and block heater interest."}, {"when": "Apr–Jun", "h": "Spring trades", "p": "Trades arrive as the snow goes. Make trade-in easy to start online."}, {"when": "Jul–Sep", "h": "Summer travel", "p": "Trans-Canada traffic peaks. Keep hours and phone numbers right on Google."}]$q$::jsonb,
   $q$[{"q": "Do we need a French website?", "a": "In Edmundston, yes. At minimum your key pages, Google profile and review replies should be in good French. If you don't have someone to write it well, say so and get help — poor French does more harm than none."}, {"q": "Can we sell to Quebec and Maine buyers?", "a": "Many stores do, but taxes, registration and warranty rules differ. Check the rules with your own advisors, then answer the common questions clearly online."}, {"q": "Is there enough search volume?", "a": "It's modest, but competition is light. A complete profile and a few good pages can make you the clear local answer."}, {"q": "What's the first fix?", "a": "Your Google profile — categories, departments, hours and a description in French and English."}]$q$::jsonb,
